EXCLUDED_SOURCE_STATUSES = frozenset({"duplicate", "misidentified", "document"})


def canonical_physical_filename(filename: str) -> str:
    name = Path(str(filename or "")).name
    return SOURCE_FILENAME_ALIASES.get(name, name)


def source_segments(filename: str) -> tuple[dict, ...]:
    canonical = canonical_physical_filename(filename)
    return tuple(
        segment for segment in SOURCE_SEGMENTS
        if segment["physical_filename"] == canonical
    )


def source_metadata_for_page(filename: str, page: int | None = None) -> dict:
    segments = source_segments(filename)
    if not segments:
        return {}
    page_number = int(page or 1)
    matching = [
        segment for segment in segments
        if int(segment["page_start"]) <= page_number <= int(segment["page_end"])
    ]
    segment = matching[0] if matching else segments[0]
    metadata = dict(segment)
    metadata["physical_filename"] = canonical_physical_filename(filename)
    metadata["source_role"] = metadata.pop("role")
    metadata["source_status"] = metadata.pop("status")
    metadata["logical_page"] = int(metadata.get("logical_page_start", 1)) + max(
        0, page_number - int(metadata.get("page_start", 1))
    )
    return metadata


def source_default_language(filename: str) -> str:
    segments = source_segments(filename)
    return str(segments[0].get("language") or "it") if segments else "it"


def source_requires_vision(filename: str, page: int | None = None) -> bool:
    metadata = source_metadata_for_page(filename, page)
    return metadata.get("text_mode") == "vision_required"


def source_is_rule_source(filename: str, page: int | None = None) -> bool:
    metadata = source_metadata_for_page(filename, page)
    if not metadata:
        return False
    return metadata.get("source_status") not in EXCLUDED_SOURCE_STATUSES


def source_import_segments(filename: str) -> tuple[dict, ...]:
    return tuple(
        segment for segment in source_segments(filename)
        if segment.get("status") not in EXCLUDED_SOURCE_STATUSES
    )


def registered_physical_filenames(*, include_excluded: bool = True) -> tuple[str, ...]:
    names = []
    for segment in SOURCE_SEGMENTS:
        if not include_excluded and segment.get("status") in EXCLUDED_SOURCE_STATUSES:
            continue
        name = str(segment["physical_filename"])
        if name not in names:
            names.append(name)
    return tuple(names)
